function isPrime(n) {
    if (n <= 1 || n == 4) {
      return false;
    }

    const limit = Math.floor(Math.sqrt(n));
    for (let i = 3; i <= limit; i += 2) {
      if (n % i === 0) {
          return false;
      }
    }

    return true;
}
